class Command(BaseCommand):
    help = 'Seed the database with 200+ realistic Indian products'

    def handle(self, *args, **kwargs):
        self.stdout.write('Creating categories...')
        cat_map = {}
        for c in CATEGORIES:
            slug = slugify(c['name'])
            cat, created = Category.objects.get_or_create(
                slug=slug,
                defaults={
                    'name': c['name'],
                    'icon': c['icon'],
                    'image_url': c['image_url'],
                }
            )
            cat_map[c['name']] = cat
            if created:
                self.stdout.write(f"  [OK] {c['name']}")

        self.stdout.write(f'\nCreating {len(PRODUCTS)} products...')
        created_count = 0
        for p in PRODUCTS:
            cat = cat_map.get(p['category'])
            if not cat:
                self.stdout.write(self.style.WARNING(f"  [SKIP] No category '{p['category']}' for {p['name']}"))
                continue
            slug = slugify(p['name'])
            # Make slug unique
            base_slug = slug
            counter = 1
            while Product.objects.filter(slug=slug).exists():
                slug = f"{base_slug}-{counter}"
                counter += 1

            product, created = Product.objects.get_or_create(
                name=p['name'],
                defaults={
                    'slug': slug,
                    'category': cat,
                    'description': p['description'],
                    'short_description': p.get('short_description', ''),
                    'price': p['price'],
                    'discount_price': p.get('discount_price'),
                    'stock': p['stock'],
                    'state_origin': p['state_origin'],
                    'rating': p['rating'],
                    'is_featured': p.get('is_featured', False),
                    'is_trending': p.get('is_trending', False),
                    'tags': p.get('tags', ''),
                    'image_url': p['image_url'],
                    'image_url_2': p.get('image_url_2', ''),
                    'image_url_3': p.get('image_url_3', ''),
                    'review_count': 0,
                }
            )
            if created:
                created_count += 1

        self.stdout.write(self.style.SUCCESS(
            f'\n[DONE] Created {created_count} products across {len(cat_map)} categories.'
        ))
